1: // Canonical model identity for binding and presence safety.
2: //
3: // Ollama may expose an implicitly tagged model as `name:latest` while the
4: // configured role binding stores `name`.  Those two spellings identify the
5: // same logical presence.  Explicit non-latest tags stay distinct, and this
6: // module deliberately does not perform family, size or quantization matching.
7: //
8: // A canonical name is not an artifact identity.  Callers that authorize a
9: // failover or claim verification must additionally bind the exact digest.
10: 
11: /**
12:  * Return the canonical key used for model presence and binding comparisons.
13:  * Invalid or empty values return null so two invalid values never compare as
14:  * the same model.
15:  *
16:  * @param {unknown} value
17:  * @returns {string|null}
18:  */
19: export function canonicalModelName(value) {
20:   if (typeof value !== 'string') return null;
21:   const normalized = value.trim().toLowerCase();
22:   if (!normalized) return null;
23:   const canonical = normalized.endsWith(':latest')
24:     ? normalized.slice(0, -':latest'.length).trimEnd()
25:     : normalized;
26:   return canonical || null;
27: }
28: 
29: /**
30:  * Compare two names using only the conservative presence identity.
31:  *
32:  * @param {unknown} left
33:  * @param {unknown} right
34:  * @returns {boolean}
35:  */
36: export function sameModelName(left, right) {
37:   const leftKey = canonicalModelName(left);
38:   const rightKey = canonicalModelName(right);
39:   return leftKey !== null && rightKey !== null && leftKey === rightKey;
40: }
41: 
42: /**
43:  * Return the exact spellings which can represent this canonical identity in
44:  * persisted name-only tables.  Explicit tags such as `:7b` do not acquire a
45:  * second, invalid `:latest` suffix.
46:  *
47:  * @param {unknown} value
48:  * @returns {string[]}
49:  */
50: export function modelNameAliases(value) {
51:   const canonical = canonicalModelName(value);
52:   if (!canonical) return [];
53:   const lastSlash = canonical.lastIndexOf('/');
54:   const lastColon = canonical.lastIndexOf(':');
55:   const hasExplicitTag = lastColon > lastSlash;
56:   return hasExplicitTag ? [canonical] : [canonical, `${canonical}:latest`];
