162:   const margin = discriminating.length > 0
163:     ? discriminating.reduce((s, t) => s + t.delta, 0) / discriminating.length
164:     : 0;
165: 
166:   return {
167:     suite: suiteName,
168:     tasks,
169:     discriminating: discriminating.length,
170:     candidateWins,
171:     incumbentWins,
172:     margin: Math.round(margin * 10000) / 10000,
173:     inconclusive: discriminating.length === 0,
174:     candidateSuiteScore: candidateRun.score,
175:     incumbentSuiteScore: incumbentRun.score,
176:     repeats: candidateRun.runs,
177:     unstableTasks: [...new Set([...candidateRun.unstableTasks, ...incumbentRun.unstableTasks])],
178:   };
179: }
