181: /**
182:  * Rozhodne souboj pro jednu roli.
183:  *
184:  * Kvalita rozhoduje, dokud rozlišuje.  Když nerozlišuje, rozhodne rychlost —
185:  * ale jen když je rozdíl výrazný, jinak se stávající model nechává být.
186:  * Setrvačnost je záměrná: výměna má cenu jen tehdy, když je pro ni důvod.
187:  *
188:  * @param {Object} comparison - výstup comparePair
189:  * @param {Object} speed - { candidate: tok/s, incumbent: tok/s }
190:  * @param {number} threshold - IMPROVEMENT_THRESHOLD pro roli
191:  */
192: export function decideRole(comparison, speed = {}, threshold = 0.05) {
193:   const { margin, candidateWins, incumbentWins, inconclusive } = comparison;
194: 
195:   if (!inconclusive) {
196:     if (margin >= threshold && candidateWins > incumbentWins) {
197:       return {
198:         winner: 'candidate',
199:         basis: 'kvalita',
200:         detail: `marže ${margin.toFixed(3)} ≥ práh ${threshold} na ${comparison.discriminating} rozlišujících úlohách `
201:           + `(${candidateWins}:${incumbentWins})`,
202:       };
203:     }
204:     if (margin <= -threshold && incumbentWins > candidateWins) {
205:       return {
206:         winner: 'incumbent',
207:         basis: 'kvalita',
208:         detail: `kandidát ztrácí ${Math.abs(margin).toFixed(3)} na ${comparison.discriminating} úlohách`,
209:       };
210:     }
211:     return {
212:       winner: 'incumbent',
213:       basis: 'kvalita',
214:       detail: `rozdíl ${margin.toFixed(3)} nedosáhl prahu ${threshold} — stávající zůstává`,
215:     };
216:   }
217: 
218:   // Kvalita nerozlišila. Rychlost rozhodne jen při zřetelném rozdílu.
219:   const c = speed.candidate;
220:   const i = speed.incumbent;
221:   if (c > 0 && i > 0) {
222:     const ratio = c / i;
223:     if (ratio >= 1.25) {
224:       return {
225:         winner: 'candidate',
226:         basis: 'rychlost',
227:         detail: `kvalita nerozlišila (všechny úlohy shodné), kandidát je ${ratio.toFixed(2)}× rychlejší `
228:           + `(${c} vs ${i} tok/s)`,
229:       };
230:     }
231:     return {
232:       winner: 'incumbent',
233:       basis: 'nerozhodně',
234:       detail: `kvalita nerozlišila a rychlost se liší jen ${ratio.toFixed(2)}× — stávající zůstává`,
235:     };
236:   }
237: 
238:   return {
239:     winner: 'incumbent',
240:     basis: 'nerozhodně',
241:     detail: 'kvalita nerozlišila a rychlost není změřená',
242:   };
243: }
