192: export function decideRole(comparison, speed = {}, threshold = 0.05) {
193:   const { margin, candidateWins, incumbentWins, inconclusive } = comparison;
194: 
195:   if (!inconclusive) {
196:     if (margin >= threshold && candidateWins > incumbentWins) {
197:       return {
198:         winner: 'candidate',
199:         basis: 'kvalita',
200:         detail: `marže ${margin.toFixed(3)} ≥ práh ${threshold} na ${comparison.discriminating} rozlišujících úlohách `
201:           + `(${candidateWins}:${incumbentWins})`,
202:       };
203:     }
204:     if (margin <= -threshold && incumbentWins > candidateWins) {
205:       return {
206:         winner: 'incumbent',
207:         basis: 'kvalita',
208:         detail: `kandidát ztrácí ${Math.abs(margin).toFixed(3)} na ${comparison.discriminating} úlohách`,
209:       };
210:     }
211:     return {
212:       winner: 'incumbent',
213:       basis: 'kvalita',
214:       detail: `rozdíl ${margin.toFixed(3)} nedosáhl prahu ${threshold} — stávající zůstává`,
215:     };
216:   }
217: 
218:   // Kvalita nerozlišila. Rychlost rozhodne jen při zřetelném rozdílu.
