30:  * Kolikrát se každá sada spustí na každém modelu.
31:  *
32:  * Jeden běh nestačí.  Změřeno 2026-08-19 na `deepseek-r1-32b`, sada `reasoning`
33:  * třikrát po sobě:
34:  *
35:  *     json_compliance   0 → 1 → 1
36:  *     czech_json        1 → 0 → 1
37:  *     skóre sady       63% → 63% → 75%
38:  *
39:  * Dvě z osmi úloh přeskakují mezi 0 a 1, protože se hodnotí binárně a model
40:  * vzorkuje (temperature 0.1).  Při jednom běhu pak `TASK_MARGIN_EPSILON` bere
41:  * náhodný přeskok za silný signál — přesně to vyrobilo protichůdná rozhodnutí,
42:  * kdy tatáž dvojice modelů na téže sadě vyšla jednou 3:0 pro kandidáta a
43:  * podruhé 0:5 pro stávajícího.
44:  */
45: export const DEFAULT_REPEATS = 3;
46: 
47: /**
48:  * Cache výsledků sady pro jeden běh.
49:  *
50:  * Role sdílejí sady: `reasoning` obsluhuje D1, D2 i R1, takže bez cache by se
51:  * pro tutéž dvojici modelů spustila třikrát a celá zkouška kandidáta by trvala
52:  * skoro dvojnásobek.  Skóre modelu na dané sadě se v rámci běhu nemění, takže
53:  * je bezpečné ho podržet; klíčem je dvojice sada+model, aby si role nemíchaly
54:  * různé stávající modely.
55:  */
56: export function createSuiteCache() {
57:   return new Map();
58: }
59: 
60: /**
61:  * Spustí sadu několikrát a shrne každou úlohu na průměr a rozptyl.
62:  *
63:  * `spread` je rozdíl mezi nejlepším a nejhorším během téže úlohy na témž
64:  * modelu — tedy kolik z pozorovaného rozdílu jde na vrub náhodě, ne kvalitě.
65:  */
66: async function runSuiteRepeated(runner, suiteName, model, repeats, onProgress, between) {
67:   const runs = [];
68:   for (let i = 0; i < repeats; i++) {
69:     if (i > 0 && between) await between();
70:     runs.push(await runner.runSuite(suiteName, model, onProgress));
71:   }
72: 
73:   const byTask = new Map();
74:   for (const run of runs) {
75:     for (const t of run.tests) {
76:       if (!byTask.has(t.name)) byTask.set(t.name, []);
77:       byTask.get(t.name).push(t.score ?? 0);
78:     }
79:   }
80: 
81:   const tasks = [...byTask.entries()].map(([name, scores]) => ({
82:     name,
83:     mean: scores.reduce((a, b) => a + b, 0) / scores.length,
84:     spread: Math.max(...scores) - Math.min(...scores),
85:     scores,
86:   }));
87: 
88:   return {
89:     suite: suiteName,
90:     model,
91:     runs: runs.length,
92:     tasks,
93:     score: tasks.reduce((s, t) => s + t.mean, 0) / (tasks.length || 1),
94:     unstableTasks: tasks.filter(t => t.spread > 0).map(t => t.name),
95:   };
96: }
97: 
98: async function runSuiteCached(runner, suiteName, model, cache, opts = {}) {
99:   const key = `${suiteName}::${model}`;
100:   if (cache?.has(key)) return cache.get(key);
101:   const result = await runSuiteRepeated(
102:     runner, suiteName, model,
103:     opts.repeats ?? DEFAULT_REPEATS,
104:     opts.onProgress,
105:     opts.between,
106:   );
107:   cache?.set(key, result);
108:   return result;
109: }
