768:   async runSuite(suiteName, modelName, onProgress) {
769:     const suite = SUITES[suiteName];
770:     if (!suite) throw new Error(`Unknown suite: ${suiteName}`);
771: 
772:     this._cancelled = false;
773:     const startTime = Date.now();
774:     const tests = [];
775:     let passedCount = 0;
776:     let totalScore = 0;
777: 
778:     // Skip vision tests if model doesn't support vision
779:     const isVision = suiteName === 'vision';
780: 
781:     for (let i = 0; i < suite.tests.length; i++) {
782:       if (this._cancelled) break;
783: 
784:       const testDef = suite.tests[i];
785:       if (onProgress) {
786:         onProgress({
787:           suite: suiteName, testName: testDef.name, status: 'running',
788:           currentTest: i + 1, totalTests: suite.tests.length,
789:           percent: Math.round((i / suite.tests.length) * 100),
790:         });
791:       }
792: 
793:       const result = await this._runTest(testDef, modelName);
794:       tests.push(result);
795:       if (result.passed) passedCount++;
796:       totalScore += result.score;
797:     }
798: 
799:     const suiteScore = suite.tests.length > 0 ? totalScore / suite.tests.length : 0;
800:     const durationMs = Date.now() - startTime;
801: 
802:     // Persist to DB
803:     if (this._db) {
804:       this._persistResults(modelName, suiteName, tests, suiteScore, passedCount, suite.tests.length, durationMs);
805:     }
806: 
807:     if (onProgress) {
808:       onProgress({
809:         suite: suiteName, testName: null, status: 'complete',
810:         currentTest: suite.tests.length, totalTests: suite.tests.length,
811:         percent: 100, score: suiteScore,
812:       });
813:     }
814: 
815:     return { suite: suiteName, model: modelName, score: suiteScore, passed: passedCount, total: suite.tests.length, tests, durationMs };
816:   }
