818:   /**
819:    * Run all relevant suites for a model.
820:    * @param {string} modelName
821:    * @param {string[]} [suiteNames] - specific suites (default: all)
822:    * @param {Function} [onProgress]
823:    */
824:   async runAll(modelName, suiteNames, onProgress) {
825:     const names = suiteNames || Object.keys(SUITES);
826:     const results = [];
827:     const startTime = Date.now();
828: 
829:     for (const name of names) {
830:       if (this._cancelled) break;
831:       const result = await this.runSuite(name, modelName, onProgress);
832:       results.push(result);
833:     }
834: 
835:     const overallScore = results.length > 0
836:       ? results.reduce((sum, r) => sum + r.score, 0) / results.length
837:       : 0;
838: 
839:     return {
840:       model: modelName,
841:       results,
842:       overallScore,
843:       durationMs: Date.now() - startTime,
844:     };
845:   }
