848:    * Persist test results + suite score to DB.
849:    */
850:   _persistResults(model, suite, tests, suiteScore, passed, total, durationMs) {
851:     try {
852:       const insertTest = this._db.prepare(`
853:         INSERT OR REPLACE INTO validation_results
854:           (model, suite, test_name, passed, score, response_preview, duration_ms, eval_tokens)
855:         VALUES (?, ?, ?, ?, ?, ?, ?, ?)
856:       `);
857: 
858:       const insertSuite = this._db.prepare(`
859:         INSERT OR REPLACE INTO validation_suite_scores
860:           (model, suite, score, passed, total, duration_ms, validated_at)
861:         VALUES (?, ?, ?, ?, ?, ?, datetime('now'))
862:       `);
863: 
864:       const tx = this._db.transaction(() => {
865:         for (const t of tests) {
866:           insertTest.run(model, suite, t.name, t.passed ? 1 : 0, t.score, t.response || '', t.durationMs || 0, t.evalTokens || 0);
867:         }
868:         insertSuite.run(model, suite, suiteScore, passed, total, durationMs);
869:       });
870:       tx();
