879:    */
880:   getResults(model) {
881:     if (!this._db) return null;
882:     try {
883:       const suiteRows = this._db.prepare(
884:         `SELECT * FROM validation_suite_scores WHERE model = ?`
885:       ).all(model);
886: 
887:       if (!suiteRows || suiteRows.length === 0) return null;
888: 
889:       const suites = {};
890:       for (const row of suiteRows) {
891:         const testRows = this._db.prepare(
