245: /**
246:  * Kompletní souboj pro jednu roli: porovná a rozhodne.
247:  */
248: export async function trialRole(runner, role, candidate, incumbent, opts = {}) {
249:   const suiteName = getSuiteForRole(role);
250:   if (!suiteName) return { role, skipped: true, reason: `role ${role} nemá validační sadu` };
251: 
252:   const comparison = await comparePair(runner, suiteName, candidate, incumbent, opts);
253:   const decision = decideRole(comparison, opts.speed || {}, opts.threshold ?? 0.05);
254: 
255:   logger.info('PairwiseTrial',
256:     `${role}: ${candidate} vs ${incumbent} → ${decision.winner} (${decision.basis}) — ${decision.detail}`);
257: 
258:   return { role, suite: suiteName, comparison, decision, skipped: false };
259: }
260: 
