61:  * Spustí sadu několikrát a shrne každou úlohu na průměr a rozptyl.
62:  *
63:  * `spread` je rozdíl mezi nejlepším a nejhorším během téže úlohy na témž
64:  * modelu — tedy kolik z pozorovaného rozdílu jde na vrub náhodě, ne kvalitě.
65:  */
66: async function runSuiteRepeated(runner, suiteName, model, repeats, onProgress, between) {
67:   const runs = [];
68:   for (let i = 0; i < repeats; i++) {
69:     if (i > 0 && between) await between();
70:     runs.push(await runner.runSuite(suiteName, model, onProgress));
71:   }
72: 
73:   const byTask = new Map();
74:   for (const run of runs) {
75:     for (const t of run.tests) {
76:       if (!byTask.has(t.name)) byTask.set(t.name, []);
77:       byTask.get(t.name).push(t.score ?? 0);
78:     }
79:   }
80: 
81:   const tasks = [...byTask.entries()].map(([name, scores]) => ({
82:     name,
83:     mean: scores.reduce((a, b) => a + b, 0) / scores.length,
84:     spread: Math.max(...scores) - Math.min(...scores),
85:     scores,
86:   }));
87: 
88:   return {
89:     suite: suiteName,
90:     model,
91:     runs: runs.length,
92:     tasks,
93:     score: tasks.reduce((s, t) => s + t.mean, 0) / (tasks.length || 1),
94:     unstableTasks: tasks.filter(t => t.spread > 0).map(t => t.name),
95:   };
96: }
